import java.util.Scanner;

public class Main {
    static final int N = 510;
    static int n, m, P;
    static long[] f = new long[N];
    static long[] g = new long[N];
    static long[][] C = new long[N][N];
    static long[][] p = new long[N][N];
    static long[][] q = new long[N][N];

    static void upd(long[] x, int y, int P) {
        x[0] = (x[0] + y) % P;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        P = sc.nextInt();

        f[0] = 1;
        for (int i = 0; i <= m; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % P;
            }
        }

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                long temp1 = (f[j - 1] * f[i - j]) % P;
                temp1 = (temp1 * (i + 1)) % P;
                temp1 = (temp1 * C[i - 1][j - 1]) % P;
                f[i] = (f[i] + temp1) % P;

                long temp2 = (f[j - 1] * g[i - j]) % P;
                long temp3 = (f[i - j] * g[j - 1]) % P;
                long sum1 = (temp2 + temp3) % P;
                sum1 = (sum1 * (i + 1)) % P;
                sum1 = (sum1 * C[i - 1][j - 1]) % P;
                g[i] = (g[i] + sum1) % P;

                long temp4 = (C[j][2] + C[i - j + 1][2]) % P;
                long temp5 = (f[j - 1] * f[i - j]) % P;
                temp4 = (temp4 * temp5) % P;
                temp4 = (temp4 * C[i - 1][j - 1]) % P;
                g[i] = (g[i] + temp4) % P;
            }
        }

        p[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(i - 1, m); j++) {
                for (int k = 0; k <= j; k++) {
                    long temp1 = (p[i - k - 1][j - k] * f[k]) % P;
                    temp1 = (temp1 * C[j][k]) % P;
                    p[i][j] = (p[i][j] + temp1) % P;

                    long temp2 = (p[i - k - 1][j - k] * g[k]) % P;
                    long temp3 = (q[i - k - 1][j - k] * f[k]) % P;
                    long sum2 = (temp2 + temp3) % P;
                    sum2 = (sum2 * C[j][k]) % P;
                    q[i][j] = (q[i][j] + sum2) % P;
                }
            }
            if (i <= m) {
                p[i][i] = f[i];
                q[i][i] = g[i];
            }
        }

        System.out.println(q[n][m]);
        sc.close();
    }
}
